import { Children } from 'react';
import './Card.css';

function Card(){
    return<>
    <div className="card">
hye i am card
    </div>
    </>
}

function CardWithImage({src}){
    return<><Card>
    <div className='img'>
        <img src={src}/>
    </div>
    </Card>
    </>
}

function CardWithTitle({Children}){
    return<><Card>
    <div className='title'>
        <span>{Children}</span>
    </div>
    </Card>
    </>
}

export {
    Card,
    CardWithTitle,
    CardWithImage
}
